// Loads the level art generated by tools/build-tiles.py: one tilesheet per level
// (rock, masonry, grass lip, platform slabs, pillar pieces...) plus the manifest
// that says where each piece sits in it. Nothing here is scaled or filtered: the
// sheets are drawn 1:1 into the level canvas, so what the PNG shows is what the
// player sees.

function loadImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('failed to load ' + url));
    img.src = url;
  });
}

export async function loadArt() {
  const manifest = await fetch('assets/tiles/manifest.json').then((r) => r.json());
  const levels = {};
  for (const id of Object.keys(manifest.levels)) {
    levels[id] = { img: await loadImage(`assets/tiles/l${id}.png`), rects: manifest.levels[id] };
  }
  const props = {};
  for (const [name, [w, h]] of Object.entries(manifest.props || {})) {
    props[name] = { img: await loadImage(`assets/props/${name}.png`), w, h };
  }
  const shard = { img: await loadImage('assets/pickups/shard.png'), ...manifest.shard };
  return { tile: manifest.tile, period: manifest.period, levels, props, shard };
}
